"""Reproducible EDA + methodology renderer: computes findings from data/processed and the published
artifacts, then writes docs/METHODOLOGY.md. No hand-typed numbers: every figure below is computed here.

Usage: uv run python -m analytics.exploration.eda
"""
from __future__ import annotations

import json

import numpy as np
import polars as pl

from analytics.data import MIN_CELL, MIN_ZONE_TRIPS, pq, zone_dim
from pipelines.common import MANIFESTS, PUBLIC, ROOT, load_ledger

A = lambda n: json.loads((PUBLIC / n).read_text())
f0 = lambda x: f"{x:,.0f}"
f1 = lambda x: f"{x:,.1f}"
f2 = lambda x: f"{x:,.2f}"
f3 = lambda x: f"{x:,.3f}"
SERV = ("fhvhv", "yellow", "green")
MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]


def table(head: list[str], rows: list[list]) -> str:
    return "\n".join(["| " + " | ".join(head) + " |", "|" + "---|" * len(head)] + ["| " + " | ".join(str(c) for c in r) + " |" for r in rows])


def eda() -> dict:
    led = load_ledger()
    out: dict = {}
    reasons = ["null_timestamp", "ts_out_of_month", "nonpositive_duration", "bad_duration", "bad_distance", "implausible_speed"]
    ex = {}
    for s in SERV:
        rs = [r for k, r in led.items() if r["service"] == s]
        ex[s] = {"raw": sum(r["raw_rows"] for r in rs), "kept": sum(r["kept"] for r in rs), "unknown_pu": sum(r["unknown_pu"] for r in rs),
                 "unknown_do": sum(r["unknown_do"] for r in rs), "unknown_od": sum(r["unknown_od"] for r in rs),
                 "tt_mismatch": sum(r["trip_time_mismatch_gt60s"] for r in rs), **{x: sum(r["exclusions"][x] for r in rs) for x in reasons}}
    out["exclusions"] = ex
    out["dist"] = pq("trip_dist_summary").to_dicts()
    sm = pq("service_month")
    out["service_month"] = sm.to_dicts()
    zm = pq("zone_month")
    zd = zone_dim(); name = dict(zip(zd["zone"], zd["name"])); bor = dict(zip(zd["zone"], zd["borough"]))
    zp = zm.group_by("zone").agg(pl.col("pickups").sum().alias("p")).sort("p", descending=True)
    tot = zp["p"].sum()
    out["top10"] = [(int(z), name[z], int(p), 100 * p / tot) for z, p in zip(zp["zone"][:10], zp["p"][:10])]
    out["top10_share"] = 100 * zp["p"][:10].sum() / tot
    out["top1pct_share"] = 100 * zp["p"][:3].sum() / tot
    out["borough_pickup_share"] = {b: 100 * sum(p for z, p in zip(zp["zone"], zp["p"]) if bor[z] == b) / tot for b in ["Manhattan", "Queens", "Brooklyn", "Bronx", "Staten Island", "EWR"]}
    od = pq("od_total")
    tk = od["trips"].sum()
    air = od.filter(pl.col("o").is_in([1, 132, 138]) | pl.col("d").is_in([1, 132, 138]))["trips"].sum()
    out["airport_share_pct"] = 100 * air / tk
    out["intrazone_share_pct"] = 100 * od.filter(pl.col("o") == pl.col("d"))["trips"].sum() / tk
    zh = pq("zone_how").filter((pl.col("period") == "all") & (pl.col("service") == "all"))
    ap = zh.filter(pl.col("zone").is_in([1, 132, 138]))
    out["airport_speed_p50"] = float(np.average(ap["speed_p50"], weights=ap["trips"]))
    out["city_speed_p50"] = float(np.average(zh["speed_p50"], weights=zh["trips"]))
    d = A("daily.json")
    tot_d = np.array([sum(x) for x in zip(*d["trips"].values())])
    out["daily"] = {"mean": float(tot_d.mean()), "max": (d["date"][int(tot_d.argmax())], int(tot_d.max())), "min": (d["date"][int(tot_d.argmin())], int(tot_d.min())),
                    "dst_spring": int(tot_d[d["date"].index("2024-03-10")]), "dst_fall": int(tot_d[d["date"].index("2024-11-03")])}
    wk = np.array([dd >= 5 for dd in [__import__("datetime").date.fromisoformat(x).weekday() for x in d["date"]]])
    out["daily"]["weekday_mean"] = float(tot_d[~wk].mean()); out["daily"]["weekend_mean"] = float(tot_d[wk].mean())
    hr = pq("hourly").group_by("hour").agg(pl.col("trips").sum().alias("t")).sort("hour")
    out["hour_share"] = {int(h): 100 * t / hr["t"].sum() for h, t in zip(hr["hour"], hr["t"])}
    return out


def render() -> str:
    e = eda()
    facts, rec, cl, net = A("facts.json"), A("reconciliation.json"), A("clusters.json"), A("network.json")
    wm, bf, val, meta = A("weather_model.json"), A("bpr_fit.json"), A("validation.json"), A("meta.json")
    L: list[str] = []
    P = L.append
    P("# Methodology and findings: Atlas of Human Mobility\n")
    P("Generated by `uv run python -m analytics.exploration.eda` from the pipeline outputs. Every number below is computed, none typed by hand. "
      "Honesty tags: OBSERVED (counted from source), DERIVED (computed from observed), PREDICTED (model output for data we have), SIMULATED (scenario output).\n")
    P("## 1. Scope and data\n")
    P("For-hire trips in New York City, 2024: yellow taxi, green taxi and high-volume FHV (Uber, Lyft, Via, Juno). No subway, bus, bike or private car, so \"demand\" means for-hire trip demand. "
      "Location granularity is the TLC taxi zone (263 areas); there are no coordinates and no trajectories. Timestamps are naive America/New_York wall clock. "
      "Weather is one station (Central Park, GHCN USW00094728) applied citywide. Sources and licence terms: `docs/DATA_SOURCES.md`.\n")
    P("## 2. Cleaning and reconciliation (OBSERVED)\n")
    P("Each raw row is assigned to exactly one outcome: the first failing rule in this order, otherwise kept. The invariant `raw = kept + sum(exclusions)` holds exactly per service-month and is asserted in `tests/test_reconciliation.py`.\n")
    P("1. `null_timestamp`: pickup or dropoff missing. 2. `ts_out_of_month`: pickup outside the file's month. 3. `nonpositive_duration`: dropoff <= pickup. 4. `bad_duration`: < 60 s or > 21,600 s. "
      "5. `bad_distance`: missing, <= 0 or > 200 miles. 6. `implausible_speed`: distance / duration > 80 mph.\n")
    ex = e["exclusions"]
    rows = []
    for s in SERV:
        x = ex[s]; exc = x["raw"] - x["kept"]
        rows.append([s, f0(x["raw"]), f0(x["kept"]), f0(exc), f"{100 * exc / x['raw']:.2f}%"] + [f0(x[r]) for r in ["ts_out_of_month", "nonpositive_duration", "bad_duration", "bad_distance", "implausible_speed"]])
    rows.append(["all", f0(facts["raw_rows_total"]), f0(facts["trips_kept_total"]), f0(facts["excluded_total"]), f"{100 * facts['excluded_total'] / facts['raw_rows_total']:.2f}%"] +
                [f0(sum(ex[s][r] for s in SERV)) for r in ["ts_out_of_month", "nonpositive_duration", "bad_duration", "bad_distance", "implausible_speed"]])
    P(table(["service", "raw rows", "kept", "excluded", "excl. %", "ts_out_of_month", "nonpositive_duration", "bad_duration", "bad_distance", "implausible_speed"], rows))
    P(f"\n`null_timestamp` totals {f0(sum(ex[s]['null_timestamp'] for s in SERV))} rows. It is a refinement over the first contract: a null can never be silently dropped or mis-bucketed.\n")
    P("**Unknown zones** (264, 265, 0, null; anything outside 1..263) stay in `kept` and in totals but are excluded from spatial and OD analytics. Pickup / dropoff / either-end counts:\n")
    P(table(["service", "unknown pickup", "unknown dropoff", "unknown either end", "% of kept with unknown either end"],
            [[s, f0(ex[s]["unknown_pu"]), f0(ex[s]["unknown_do"]), f0(ex[s]["unknown_od"]), f"{100 * ex[s]['unknown_od'] / ex[s]['kept']:.2f}%"] for s in SERV]))
    P(f"\nThe unknown-zone mass is mostly FHV drop-offs (in a January 2024 spot check, every unknown fhvhv drop-off was code 265, \"outside NYC\"). Platform `trip_time` differs from dropoff minus pickup by more than 60 s in {f0(sum(ex[s]['tt_mismatch'] for s in SERV))} kept FHV trips, so the timestamp difference is used throughout.\n")
    P("## 3. Exploratory findings (OBSERVED / DERIVED)\n")
    P("### 3.1 Distributions and outliers\n")
    P(table(["service", "trips", "median mi", "p99 mi", "median min", "p99 min", "median mph", "p1 mph", "p99 mph", "p99.99 mph"],
            [[r["service"], f0(r["n"]), f2(r["p50_mi"]), f1(r["p99_mi"]), f1(r["p50_s"] / 60), f1(r["p99_s"] / 60), f1(r["p50_mph"]), f1(r["p01_mph"]), f1(r["p99_mph"]), f1(r["p9999_mph"])] for r in e["dist"]]))
    P("\nAll figures are after cleaning. Raw files contain impossible values (negative or zero durations, multi-day trips, zero-mile and > 200-mile trips, > 80 mph); they account for the exclusion counts above. "
      "Remaining right tails (p99 durations, long airport and out-of-town trips) are real and kept.\n")
    P("### 3.2 Service mix by month\n")
    sm = pl.DataFrame(e["service_month"])
    rows = []
    for m in range(1, 13):
        s = sm.filter(pl.col("month") == m); t = s["kept"].sum()
        g = lambda x: s.filter(pl.col("service") == x)["kept"][0]
        rows.append([MONTHS[m - 1], f0(t)] + [f"{100 * g(x) / t:.1f}%" for x in SERV])
    P(table(["month", "kept trips", "fhvhv", "yellow", "green"], rows))
    P(f"\nFor the year: fhvhv {f2(facts['share_pct']['fhvhv'])}%, yellow {f2(facts['share_pct']['yellow'])}%, green {f2(facts['share_pct']['green'])}% of {f0(facts['trips_kept_total'])} kept trips "
      f"(mean {f1(facts['trips_per_minute_mean'])} trips per minute). Green taxis are too small for most zone-hour analyses and are suppressed heavily (section 6).\n")
    P("### 3.3 Temporal patterns\n")
    d = e["daily"]
    P(f"- Mean {f0(d['mean'])} trips/day; weekdays {f0(d['weekday_mean'])}, weekend days {f0(d['weekend_mean'])}.\n- Busiest day {d['max'][0]} ({f0(d['max'][1])}); quietest {d['min'][0]} ({f0(d['min'][1])}).\n"
      f"- Citywide weekday peaks: AM {facts['am_peak_hour']['label']}, PM {facts['pm_peak_hour']['label']}; weekend peak {facts['weekend_peak_hour']['label']}.\n"
      f"- The single busiest zone-hour-of-week is {facts['busiest_zone_how']['name']} on {facts['busiest_zone_how']['how_label']} ({f0(facts['busiest_zone_how']['mean_trips'])} pickups per such hour on average).\n"
      f"- DST days: 2024-03-10 ({f0(d['dst_spring'])} trips, hour 02:00 absent) and 2024-11-03 ({f0(d['dst_fall'])} trips, hour 01:00 occurs twice and both occurrences land in wall-clock hour 1).\n")
    hs = e["hour_share"]
    P("Share of all trips by pickup hour (%): " + ", ".join(f"{h:02d}h {v:.1f}" for h, v in hs.items()) + ".\n")
    P("### 3.4 Geographic concentration\n")
    P(table(["rank", "zone", "name", "pickups", "share"], [[i + 1, z, n, f0(p), f"{s:.2f}%"] for i, (z, n, p, s) in enumerate(e["top10"])]))
    P(f"\nThe top 10 zones account for {f1(e['top10_share'])}% of known-zone pickups; {facts['zones_for_half_pickups']} of 263 zones are needed to reach 50%. "
      "Pickup share by borough: " + ", ".join(f"{b} {f1(v)}%" for b, v in e["borough_pickup_share"].items()) + ". "
      f"Manhattan-to-Manhattan trips are {f1(facts['mn_internal_share_pct'])}% of trips starting in Manhattan; Brooklyn-internal {f1(facts['bk_internal_share_pct'])}% (computed pre-suppression). "
      f"Intrazone trips (origin = destination) are {f1(e['intrazone_share_pct'])}% of known-zone OD trips. Trips touching EWR, JFK or LaGuardia are {f1(e['airport_share_pct'])}%. "
      f"Zones 132 and 138 reach {facts['airport_dest_zone_count']} distinct destination zones. The busiest directed corridor is {facts['top_od_pair']['o_name']} to {facts['top_od_pair']['d_name']} ({f0(facts['top_od_pair']['trips'])} trips); "
      f"including intrazone pairs the busiest is zone {facts['top_od_pair_incl_intrazone']['o']} within itself ({f0(facts['top_od_pair_incl_intrazone']['trips'])}).\n")
    P("### 3.5 Missingness, leakage and bias notes\n")
    P(f"- **Platform-reported HVFHV fields.** `trip_miles` and `trip_time` come from the platforms, which TLC says it cannot verify. Speeds are derived from them, so speed is a proxy, not measured road speed. Trips that fail validation are dropped, which could bias speeds if failures correlate with congestion (not testable here).\n"
      f"- **Airport effect.** Airport-zone trips (1, 132, 138) have a trip-weighted median speed of {f1(e['airport_speed_p50'])} mph versus {f1(e['city_speed_p50'])} mph citywide; they are long, highway trips and inflate speed in a few zones. Clustering and BPR are fit at zone and borough level, where this mixing is partly absorbed; it is not removed.\n"
      "- **Speed is conditioned on trip distance mix.** A zone's median speed mixes short slow trips and long fast ones; midday and overnight differences partly reflect trip length, not only traffic.\n"
      "- **DST.** Naive wall-clock timestamps cannot separate the repeated 01:00 hour on 2024-11-03; that Sunday-01:00 hour-of-week mean is inflated by about 1/52 (1.9%). The 02:00 Sunday cell has 52 occurrences, not 53; denominators are derived from the data (distinct dates with trips), so the missing hour is handled.\n"
      "- **Survivorship and selection.** Only completed, recorded trips exist. Demand that was never served, or trips that took other modes, are invisible.\n"
      "- **Single weather station.** Central Park rain is applied to every zone.\n"
      "- **Ecological fallacy.** Zone-level patterns say nothing about individuals; only aggregates are published.\n")
    P("## 4. Methods\n")
    P("### 4.1 Time bucketing and zone dimension\n")
    P(f"Hour = hour of the pickup timestamp; day of week Monday = 0; hour-of-week = dow * 24 + hour. Hour-of-week means divide annual counts by the number of distinct dates on which that (dow, hour) occurs. "
      f"Zone polygons come from the TLC shapefile (EPSG:2263), reprojected to WGS84 with pyproj, simplified with a {meta['zones_simplify_tolerance_deg']} degree tolerance (Douglas-Peucker, topology preserving), coordinates rounded to 5 decimals; "
      f"the shapefile has one record per LocationID 1..263 (no duplicate IDs to dissolve; the code dissolves any that appear). `zones.geojson` is {f0(meta['artifact_bytes']['zones.geojson'])} bytes. "
      "Transform correctness is tested against JFK (132), Times Square (230) and Central Park (43).\n")
    P("### 4.2 Hour bands\n")
    P(table(["id", "label", "hours"], [[b["id"], b["label"], f"{b['hours'][0]}-{b['hours'][-1]}"] for b in meta["bands"]]))
    P("\n### 4.3 Hour-of-week profiles, peak hours, corridors\n")
    P("Profiles are zone x hour-of-week pickup means per service and for all services. Peak hours are argmax of citywide mean trips: weekday search windows 05-11 (AM) and 15-21 (PM); weekend Sat+Sun mean. "
      "Corridors are directed OD pairs with origin != destination and known zones; per band the top 300 (and top 2000 for all hours) with >= 11 trips are published with exact (not approximate) p10/p50/p90 duration and speed.\n")
    P("### 4.4 Congestion indicator\n")
    P(f"For each zone, free-flow speed = the 85th percentile of the zone's hour-of-week median speeds over 02:00-05:59 (up to 28 cells, each needing >= {MIN_CELL} trips; zone needs >= 14 valid cells), all services pooled. "
      "`speed_ratio` = hour-of-week median speed / that free-flow speed (below 1 means slower than the zone's own overnight speed). Borough free flow uses the same rule on borough-level medians. "
      "Why p85 and not the median: the median of overnight speeds includes late-night noise and slow bar-closing traffic; p85 is a standard free-flow proxy. Robustness to this choice is in 5.5. It is a proxy built from for-hire trips, not a measured road speed.\n")
    P("Borough AM-peak (weekday 06-09) speed as a share of free flow: " + ", ".join(f"{b} {f1(v['speed_ratio_pct'])}% ({f1(v['am_peak_median_speed_mph'])} of {f1(v['free_flow_mph'])} mph)" for b, v in facts["borough_am_peak_speed_ratio"].items()) + ".\n")
    P("### 4.5 Network\n")
    P(f"Weighted directed graph of known-zone OD pairs with origin != destination and >= 11 trips ({f0(net['n_edges'])} edges). PageRank: damping 0.85, weight = trips. In/out strength = sum of trips. "
      "Betweenness: shortest paths with edge length = 1/trips, so heavy flows are short links and paths prefer well-travelled corridors; computed exactly (263 nodes, no sampling). "
      f"The highest-betweenness (hinge) zone is {facts['hinge_zone']['name']}. Interpretation caution: betweenness here measures position in the flow-weighted graph, not physical routing, and airports score high because they connect to almost every zone with large flows.\n")
    P("### 4.6 Zone clustering\n")
    c = val["clustering"]
    P(f"Features: each zone's 168-hour mean pickup profile (all services), L1-normalized so only the shape of the week matters. Zones with fewer than {MIN_ZONE_TRIPS} annual pickups are excluded ({len(cl['excluded_zones'])} zones, including those with no pickups; the rest are listed in `clusters.json`). "
      "K-means (n_init 10, fixed seed), k in 3..8 chosen by silhouette:\n")
    P(table(["k", "silhouette"], [[k, f3(v)] for k, v in cl["silhouette_by_k"].items()]))
    P(f"\nChosen k = {cl['k']} (silhouette {f3(cl['silhouette'])}). That is the bottom of the allowed range: silhouette falls as k grows, so the data support a coarse typology (k = 4 scores {f3(cl['silhouette_by_k']['4'])}), and we report that rather than forcing more clusters. "
      f"Stability: adjusted Rand index against the reference solution over {cl['stability_ari']['n_seeds']} other seeds: mean {f3(cl['stability_ari']['ari_mean'])}, min {f3(cl['stability_ari']['ari_min'])}. "
      f"Baseline: the same cluster sizes with randomly permuted labels give silhouette mean {f3(cl['random_label_silhouette']['mean'])} (max {f3(cl['random_label_silhouette']['max'])}).\n")
    P("Labels come from a documented rule on the centroid (ratios to the citywide shape): " + cl["label_rule"] + ".\n")
    P(table(["id", "label", "zones", "share of trips", "night x", "weekend x", "AM x", "PM x"],
            [[x["id"], x["label"], x["size"], f"{100 * x['share_of_trips']:.1f}%"] + [f2(x["feature_ratios_vs_city"][k]) for k in ("night", "wkend", "am", "pm")] for x in cl["clusters"]]))
    P("\n### 4.7 Weather association\n")
    P("Dependent variable log(daily kept trips, all services), 366 days. Regressors: precipitation, snow-day indicator, TMAX per 10 C, day-of-week dummies, month dummies, federal-holiday indicator (11 days in 2024). "
      "OLS with Newey-West (HAC) standard errors, 7 lags. Two specifications: `bins` (dry < 0.1 mm is the reference; light 0.1-2.5, moderate 2.5-12.7, heavy > 12.7 mm) and `continuous` (PRCP in mm). "
      "**This is an association, not a causal effect**: single station, no control for events, outages or strikes, and month dummies absorb seasonal temperature so TMAX is identified within-month.\n")
    for key in ("bins", "continuous"):
        m = wm["models"][key]
        P(f"\n`{key}`: n = {m['n']}, R^2 = {f3(m['r2'])}, adj. R^2 = {f3(m['adj_r2'])}. Selected terms (percent change in daily trips per unit, 95% CI):\n")
        keep = [x for x in m["coefficients"] if x["term"].startswith(("prcp", "snow", "tmax", "holiday")) or x["term"] in ("dow_sat", "dow_sun")]
        P(table(["term", "effect %", "95% CI low", "95% CI high", "p"], [[x["term"], f2(100 * x["pct_effect"]), f2(100 * x["pct_ci_lo"]), f2(100 * x["pct_ci_hi"]), f"{x['p']:.3f}"] for x in keep]))
    pe = wm["prcp_effect_10mm"]
    P(f"\nHeadline: each additional 10 mm of rain is associated with {f2(pe['pct'])}% more daily trips (95% CI {f2(pe['ci_low_pct'])}% to {f2(pe['ci_high_pct'])}%), spec: {pe['spec']}. "
      "Rain is associated with higher, not lower, for-hire demand, plausibly substitution from walking and transit; we do not claim that mechanism. The linear-in-mm form is a simplification (the bins model shows the heavy-rain bin is the largest).\n")
    P("### 4.8 BPR scenario model (SIMULATED output, OBSERVED fit data)\n")
    P("For a borough b and hour-of-week h: v = mean trips per hour (all services, pickup in the borough); TTI = free_flow_speed / median_speed (equivalently t / t0). "
      "BPR: TTI = 1 + alpha * (v / C)^beta. alpha and beta are fitted by bounded nonlinear least squares (scipy `least_squares`, alpha in [0, 50], beta in [0.2, 10], six starts). "
      "**Identifiability:** alpha, beta and C cannot all be recovered from (v, TTI) pairs, because alpha * C^-beta is the only combination that matters. We therefore fix C := the borough's p95 hourly volume (a normalization, not an engineered road capacity; `capacity_index`, trips/hour), and alpha is identified. "
      "Scenario functions (pure, in `analytics/bpr.py`, mirrored by `bpr_test_vectors.json`):\n")
    P("- `scenario_speed(obs, v, C, alpha, beta, dm, cm) = obs * (1 + alpha (v/C)^beta) / (1 + alpha (v dm / (C cm))^beta)` : anchored to the observed speed; exactly `obs` at dm = cm = 1 (tested).\n"
      "- `scenario_fitted_speed(ff, v, C, alpha, beta, dm, cm) = ff / (1 + alpha (v dm / (C cm))^beta)` : the model curve; equals the fitted baseline at dm = cm = 1 (tested).\n")
    rows = []
    for b, d in bf["boroughs"].items():
        h = d["holdout"]["borough_level"]
        rows.append([b, f1(d["free_flow_mph"]), f0(d["capacity_index"]), f3(d["alpha"]), f3(d["beta"]), f3(d["r2"]), f3(d["rmse"]), f3(d["x_max_observed"]),
                     f3(h["test"]["r2_vs_const"]), f3(h["test"]["rmse"]), f3(h["test"]["rmse_const_train_mean"]), f3(h["test"]["rmse_freeflow_const"])])
    P("Borough fits on the full year (168 hour-of-week points each), and temporal holdout (parameters, free flow and C from Jan-Sep only; scored on Oct-Dec):\n")
    P(table(["borough", "free flow mph", "C trips/h", "alpha", "beta", "R^2 (fit)", "RMSE (fit)", "max v/C", "holdout R^2 vs const", "holdout RMSE", "RMSE const train-mean", "RMSE free-flow const"], rows))
    P("\nZone-pooled fits (thousands of zone-hour points per borough) give a harder test:\n")
    rows = [[b, d["holdout"]["zone_level"]["train"]["n"], f3(d["holdout"]["zone_level"]["alpha"]), f3(d["holdout"]["zone_level"]["beta"]), f3(d["holdout"]["zone_level"]["train"]["r2"]),
             f3(d["holdout"]["zone_level"]["test"]["r2_vs_const"]), f3(d["holdout"]["zone_level"]["test"]["rmse"]), f3(d["holdout"]["zone_level"]["test"]["rmse_const_train_mean"])] for b, d in bf["boroughs"].items()]
    P(table(["borough", "train n", "alpha", "beta", "train R^2", "holdout R^2 vs const", "holdout RMSE", "RMSE const"], rows))
    P(f"\n**Reading the fit honestly.** Demand and speed both follow the clock, so v/C is partly a proxy for time of day; the curve describes how pace co-varies with volume across the week, which is not proof that adding demand would slow traffic by the same amount. "
      "Fitted beta is near 1 in most boroughs (classic BPR uses 4), so the curve is close to linear in v/C and extrapolation beyond max v/C (above) is not supported by data; the site must flag it. "
      f"R^2 values are moderate (borough level {f2(min(d['r2'] for d in bf['boroughs'].values()))} to {f2(max(d['r2'] for d in bf['boroughs'].values()))}, zone-pooled train {f2(min(d['holdout']['zone_level']['train']['r2'] for d in bf['boroughs'].values()))} to {f2(max(d['holdout']['zone_level']['train']['r2'] for d in bf['boroughs'].values()))}): volume explains a meaningful but incomplete share of pace variation. The holdout metrics track the in-sample ones, so there is no overfitting signal, but the model is cross-sectional in time-of-week, not a causal traffic model.\n")
    P("## 5. Validation\n")
    P("### 5.1 Reconciliation\nRaw rows equal kept plus exclusions per service-month; published zone_month, od_matrix_totals and daily totals reconcile to kept rows after unknown-zone and suppressed counts (`tests/test_reconciliation.py`). A slow test re-counts raw and interim Parquet.\n")
    P("### 5.2 Baselines\nBPR is compared with (a) a constant free-flow baseline (TTI = 1) and (b) a constant equal to the training mean TTI; it must beat both on the Oct-Dec holdout (asserted in `tests/test_models.py`). Clustering is compared with randomly permuted labels (4.6).\n")
    P("### 5.3 Temporal holdout\nSee 4.8: fit on Jan-Sep, scored on Oct-Dec, with free-flow speed and C also taken from the training period.\n")
    P("### 5.4 Reproducibility\nAll randomness is seeded; artifacts contain no wall-clock timestamps (`generated_at` is the latest raw retrieval time). Tests hash two runs of k-means and of the BPR fit and require equality; the whole artifact set is rebuilt from raw by `uv run python -m pipelines.run_all`.\n")
    P("### 5.5 Robustness to the free-flow definition\nBorough beta (R^2) when free flow is defined differently:\n")
    P(table(["definition"] + list(bf["boroughs"]), [[n] + [f"{f2(v[b]['beta'])} ({f2(v[b]['r2'])})" for b in bf["boroughs"]] for n, v in val["ff_robustness"].items()]))
    P("\nR^2 is stable across definitions, but beta moves (for example the median definition raises beta), so beta should be read as definition-dependent. This is the main sensitivity of the scenario model and is shown to the user as a limitation.\n")
    P("## 6. Small-cell suppression and ethics\n")
    sup = rec["suppression"]
    P(f"Cells with 1 to 10 trips are suppressed (null) in every published count; zero stays zero. The headline suppressed figure is the {f0(rec['suppressed_trips_total'])} trips in OD pairs with fewer than 11 annual trips withheld from `od_matrix_totals.json`. "
      f"Across all artifacts {f0(rec['suppressed_cells_total'])} cells were suppressed (artifacts overlap, so per-artifact figures in `reconciliation.json` must not be added). Only aggregates are published; no trajectories or individuals.\n")
    P("## 7. Failure cases and limitations\n")
    P("- The BPR relation is correlational and nearly linear; scenarios far outside observed v/C are extrapolation.\n- Clustering finds a coarse typology (k = 3 by silhouette); finer neighborhood types are not supported by weekly-shape alone.\n"
      "- Speed is a for-hire proxy; slow zones with few trips have noisy medians and are masked below 30 trips.\n- Weather: one station, daily resolution, association only.\n- Betweenness favours airports and the Manhattan core.\n"
      "- Zones with no or few pickups (including EWR) are excluded from clustering and BPR.\n- The first-pass contract named five exclusion reasons; `null_timestamp` was added, and bad distance includes missing or NaN values.\n")
    return "\n".join(L) + "\n"


